STOREFRONT_URI = "ui://widget/raksul-storefront.html"

STOREFRONT_HTML = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
:root{color-scheme:light dark;--bg:#fff;--panel:#f5f5f2;--text:#191918;--muted:#6b6b66;--line:#dddcd7;--accent:#e54824;--ok:#177447;--bad:#b42318}@media(prefers-color-scheme:dark){:root{--bg:#1d1d1b;--panel:#292927;--text:#f4f3ee;--muted:#aaa9a2;--line:#45453f;--accent:#ff7654;--ok:#52b788;--bad:#ff7b72}}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,sans-serif}.shell{max-width:1100px;margin:auto;padding:14px}header{display:flex;justify-content:space-between;align-items:center}h1,h2{margin:0}.badge{color:var(--accent);font-weight:800}.notice,.panel,.status{background:var(--panel);border-radius:10px;padding:11px;margin:12px 0}.muted{color:var(--muted)}form,.row{display:flex;gap:8px}.login form{display:grid;grid-template-columns:1fr 1fr auto;margin-top:10px}input,select,button{font:inherit;color:var(--text);background:var(--bg);border:1px solid var(--line);border-radius:9px;padding:9px;min-width:0}button{cursor:pointer;font-weight:700}.primary{background:var(--accent);border-color:var(--accent);color:#fff}.approve{background:var(--ok);border-color:var(--ok);color:#fff}.reject{color:var(--bad)}button:disabled{opacity:.45}.search input{flex:1}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:14px}.products{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}.card,.cart{border:1px solid var(--line);border-radius:12px;overflow:hidden}.media{height:145px;display:grid;place-items:center;background:var(--panel);color:var(--muted)}.media img{width:100%;height:145px;object-fit:contain}.pad,.cart{padding:10px}.name{font-weight:750;min-height:42px}.price{font-size:16px;font-weight:800;margin:5px 0}.choices,.actions{display:grid;gap:7px;margin:9px 0}.choices label{display:grid}.cart{position:sticky;top:8px;align-self:start}.line{border-top:1px solid var(--line);padding:9px 0}.line input{width:65px}.line span{flex:1}.total{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:9px;font-weight:800}.receipt{border:2px solid var(--ok)}[hidden]{display:none!important}@media(max-width:720px){.login form,.layout{grid-template-columns:1fr}.cart{position:static}}
</style></head><body><main class="shell"><header><h1>RAKSUL Database Storefront</h1><span class="badge">MOCK ONLY</span></header><div class="notice">Products come from PostgreSQL. No supplier website opens. No password, card details, or real payment is used.</div><section class="panel login" id="login"><h2>Mock sign in</h2><div class="muted">Name and email identify this local demo session.</div><form id="loginForm"><input id="name" required maxlength="120" placeholder="Name"><input id="email" required maxlength="254" type="email" placeholder="Email"><button class="primary">Enter storefront</button></form></section><section id="store" hidden><div class="status" id="customer"></div><form class="search" id="searchForm"><input id="query" placeholder="Search database products"><button class="primary">Search</button></form><p id="message" class="muted"></p><div class="layout"><section class="products" id="products"></section><aside class="cart" id="cart"></aside></div></section></main><script>
const S={products:[],session:null,cart:null,order:null,confirmation:null,busy:false},P=new Map();let N=1;function rpc(method,params={}){const id=N++;parent.postMessage({jsonrpc:"2.0",id,method,params},"*");return new Promise((resolve,reject)=>P.set(id,{resolve,reject}))}function unwrap(v){return v?.structuredContent||v?.structured_content||v||{}}async function tool(name,args){S.busy=true;draw();try{const raw=window.openai?.callTool?await window.openai.callTool(name,args):await rpc("tools/call",{name,arguments:args}),out=unwrap(raw);if(out.status==="error")throw Error(out.error?.message||"Tool failed");return out}finally{S.busy=false;draw()}}addEventListener("message",e=>{const m=e.data;if(!m||m.jsonrpc!=="2.0")return;if(m.id&&P.has(m.id)){const p=P.get(m.id);P.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);return}if(m.method==="ui/notifications/tool-result")seed(unwrap(m.params))});function seed(o){if(o.results)S.products=o.results;if(o.session)S.session=o.session;if(o.cart)S.cart=o.cart;if(o.order)S.order=o.order;if(o.confirmation)S.confirmation=o.confirmation;draw()}function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function yen(n){return Number.isInteger(n)?`¥${n.toLocaleString()}`:"Price unavailable"}function auth(){return{session_id:S.session.id}}function say(t,bad=false){const e=document.getElementById("message");e.textContent=t;e.style.color=bad?"var(--bad)":"var(--muted)"}
function select(label,values,id){return values?.length?`<label>${label}<select id="${id}"><option value="">Select ${label.toLowerCase()}</option>${values.map(v=>`<option>${esc(v)}</option>`).join("")}</select></label>`:""}function card(p){const media=p.image_url?`<div class="media"><img src="${esc(p.image_url)}" alt="" onerror="this.remove();this.parentElement.textContent='No image'"></div>`:`<div class="media">No image</div>`;return `<article class="card">${media}<div class="pad"><div class="name">${esc(p.name)}</div><div class="muted">${esc(p.brand||p.category_name||"")}</div><div class="price">${yen(p.price_jpy)}</div><div class="choices">${select("Color",p.colors,`color-${p.id}`)}${select("Size",p.sizes,`size-${p.id}`)}<label>Quantity<input id="qty-${p.id}" type="number" min="1" max="100" value="1"></label></div><button class="primary" ${p.price_jpy==null||S.busy?"disabled":""} onclick="add(${p.id})">Add to cart</button></div></article>`}
function cart(){const c=S.cart;if(!c)return"<h2>Cart</h2><p>Sign in first.</p>";const lines=c.items.map(i=>`<div class="line"><strong>${esc(i.name)}</strong><div class="muted">${[i.color,i.size].filter(Boolean).map(esc).join(" · ")}</div><div class="row"><input type="number" min="1" max="100" value="${i.quantity}" onchange="qty(${i.item_id},this.value)"><span>${yen(i.line_total_jpy)}</span><button onclick="removeLine(${i.item_id})">Remove</button></div></div>`).join("");let next="";if(S.order?.status==="pending"&&S.confirmation)next=`<div class="status"><strong>Explicit mock confirmation</strong><p>Total ${yen(S.order.total_jpy)}</p><div class="actions"><button class="approve" onclick="decide('approve')">Approve mock payment</button><button class="reject" onclick="decide('reject')">Reject mock payment</button></div></div>`;else if(S.order?.status==="approved")next=`<div class="status receipt"><strong>Mock receipt</strong><p>Order ${esc(S.order.id)}</p><p>Total ${yen(S.order.total_jpy)}</p><p>No money moved.</p></div>`;else if(S.order?.status==="rejected")next=`<div class="status"><strong>Rejected</strong><p>Cart preserved. Edit it or retry.</p></div>`;return `<h2>Cart · ${c.item_count}</h2>${lines||'<p class="muted">Empty cart.</p>'}<div class="total"><span>Total</span><span>${yen(c.total_jpy)}</span></div><div class="actions"><button class="primary" ${!c.items.length||c.status!=="active"||S.busy?"disabled":""} onclick="checkout()">Review mock purchase</button></div>${next}`}
function draw(){document.getElementById("login").hidden=!!S.session;document.getElementById("store").hidden=!S.session;if(!S.session)return;document.getElementById("customer").innerHTML=`Signed in locally as <strong>${esc(S.session.customer.name)}</strong> · expires ${new Date(S.session.expires_at).toLocaleString()}`;document.getElementById("products").innerHTML=S.products.map(card).join("")||'<p class="muted">No database products found.</p>';document.getElementById("cart").innerHTML=cart()}
document.getElementById("loginForm").addEventListener("submit",async e=>{e.preventDefault();try{let o=await tool("mock_sign_in",{name:document.getElementById("name").value,email:document.getElementById("email").value});S.session=o.session;o=await tool("create_cart",auth());S.cart=o.cart;say("Mock session and cart created.")}catch(x){alert(x.message)}draw()});document.getElementById("searchForm").addEventListener("submit",async e=>{e.preventDefault();try{const o=await tool("search_products",{query:document.getElementById("query").value||null,limit:20});S.products=o.results||[];say(`${S.products.length} database product(s).`)}catch(x){say(x.message,true)}draw()});async function add(id){try{const p=S.products.find(x=>x.id===id),color=document.getElementById(`color-${id}`)?.value||null,size=document.getElementById(`size-${id}`)?.value||null,quantity=Number(document.getElementById(`qty-${id}`).value);if(p.colors?.length&&!color)throw Error("Select a color.");if(p.sizes?.length&&!size)throw Error("Select a size.");const o=await tool("add_cart_item",{...auth(),cart_id:S.cart.id,product_id:id,quantity,color,size});S.cart=o.cart;S.order=S.confirmation=null;say("Added to cart.")}catch(x){say(x.message,true)}draw()}async function qty(id,value){try{const o=await tool("update_cart_item",{...auth(),cart_id:S.cart.id,item_id:id,quantity:Number(value)});S.cart=o.cart;S.order=S.confirmation=null}catch(x){say(x.message,true)}draw()}async function removeLine(id){try{const o=await tool("remove_cart_item",{...auth(),cart_id:S.cart.id,item_id:id});S.cart=o.cart;S.order=S.confirmation=null}catch(x){say(x.message,true)}draw()}async function checkout(){try{const o=await tool("create_mock_checkout",{...auth(),cart_id:S.cart.id});S.order=o.order;S.confirmation=o.confirmation;say("Explicitly approve or reject this mock purchase.")}catch(x){say(x.message,true)}draw()}async function decide(decision){try{const o=await tool("decide_mock_payment",{...auth(),order_id:S.order.id,confirmation_token:S.confirmation.token,decision});S.order=o.order;S.confirmation=null;if(decision==="approve")S.cart.status="checked_out";say(decision==="approve"?"Mock receipt created. No money moved.":"Rejected. Cart available for changes or retry.")}catch(x){say(x.message,true)}draw()}
(async()=>{try{if(!window.openai?.callTool)await rpc("ui/initialize",{appInfo:{name:"raksul-database-storefront",version:"2.0.0"},capabilities:{}})}catch(_){}if(window.openai?.toolOutput)seed(unwrap(window.openai.toolOutput));draw()})();
</script></body></html>"""
